mapper.codeEditorJavascript:
// -- Modul 2 - Betreff lesen ----------------------------------------------
// Der Betreff ist die alleinige Wahrheit. Das PDF wird bewusst NICHT
// gegengelesen, deshalb wird hier streng geprueft: exakt drei Segmente,
// ein erkennbarer Titel, harte Muster fuer Rechnungsnummer und Datum.
//
// Das Datum wird rein per String rekomponiert (Date.UTC + Rueckvergleich).
// Kein parseDate, keine Zeitzone - ein Datum mit Zone wuerde Airtable als
// UTC lesen und im Zweifel den Vortag speichern.

const ABSENDER = 'kontakt@selectedleafs.com';
const BASE  = 'appiIkOaz1ID1FjfE';
const T_UMS = 'tbl0Xqw2eK7KPVVWY';
const T_BLG = 'tbld7UQwDBbq9A8Xk';

const leer = {
  status: '', hinweis: '', belegtyp: '', rechnung: '', datum: '',
  betreff: '', dateiname: '', url_umsatz: '', url_dublette: ''
};

// -- Absender --------------------------------------------------------------
// Der Mailhook haengt die Absenderadresse je nach Feldform an verschiedene
// Stellen. Statt einen Pfad zu raten werden mehrere angeboten, der erste
// brauchbare gewinnt. Aus '<a@b.de>' oder 'Name <a@b.de>' wird 'a@b.de'.
const mail = function (v) {
  let s = '';
  if (v != null) {
    s = (typeof v === 'object')
      ? String(v.address || v.email || v.value || '')
      : String(v);
  }
  const m = s.match(/[^\s<>,;"]+@[^\s<>,;"]+/);
  return m ? m[0].trim().toLowerCase() : '';
};

const sender = mail(input.sender_a) || mail(input.sender_b) || mail(input.sender_c);

// -- Anhang ----------------------------------------------------------------
let anh = input.anhang;
if (typeof anh === 'string') {
  try { anh = JSON.parse(anh); } catch (e) { anh = null; }
}
if (!Array.isArray(anh)) anh = anh ? [anh] : [];

const anzahl = anh.length;
const a0 = anh[0] || {};
const mime = String(a0.contentType || a0.mimeType || a0.type || a0.mime || '').toLowerCase();

// Diagnose fuer den Fall, dass die Bundle-Struktur wieder anders aussieht.
const felder = Object.keys(a0).join(', ');
const diagnose = 'Felder im Anhang-Bundle: ' + (felder || 'keine.');

const betreff = String(input.betreff || '').trim();

// Absender nicht lesbar -> laut scheitern. Ein stiller Abbruch saehe hier
// genauso aus wie "alles in Ordnung, nichts zu tun".
if (!sender) {
  return Object.assign({}, leer, {
    status: 'problem',
    betreff: betreff,
    hinweis: 'Absender der Mail nicht lesbar - keiner der bekannten Pfade traegt eine Adresse. ' + diagnose
  });
}

// Fremde Post an die Hook-Adresse: still verwerfen, keine Meldung.
if (sender !== ABSENDER) {
  return Object.assign({}, leer, { status: 'fremd' });
}

const probleme = [];

if (anzahl !== 1) {
  probleme.push('Erwartet wird genau ein Anhang, angekommen sind ' + anzahl + '. ' + diagnose);
}
if (mime && mime.indexOf('application/pdf') !== 0) {
  probleme.push('Der Anhang ist kein PDF (' + mime + ').');
}

let belegtyp = '';
let rechnung = '';
let datum = '';

if (betreff.indexOf('[BELEG] ') !== 0) {
  probleme.push('Betreff beginnt nicht mit "[BELEG] ".');
} else {
  const teile = betreff.slice(8).split('|').map(function (t) { return t.trim(); });

  if (teile.length !== 3) {
    probleme.push('Betreff traegt ' + teile.length + ' statt 3 mit "|" getrennte Angaben.');
  } else {
    // -- Belegtyp per STICHWORT, nicht per exaktem Titel ------------------
    // Steht "Mahnung" im Titel, ist es eine Mahnung - egal welche Stufe:
    // "1. Mahnung", "2. Mahnung", "Letzte Mahnung", "Letzte aussergericht-
    // liche Mahnung". Airtable kennt nur den einen Belegtyp, die Stufe
    // spielt dort keine Rolle.
    //
    // "Mahnbescheid" enthaelt das Wort "Mahnung" NICHT und faellt damit
    // korrekt durch - der gerichtliche Weg gehoert nicht in diese Kette.
    const titel = teile[0];
    const t = titel.toLowerCase();
    const hatErinnerung = t.indexOf('zahlungserinnerung') >= 0;
    const hatMahnung    = t.indexOf('mahnung') >= 0;

    if (hatErinnerung && hatMahnung) {
      // Beide Stichworte im Titel: nicht entscheidbar, also nicht entscheiden.
      probleme.push('Titel "' + titel + '" nennt Zahlungserinnerung UND Mahnung - nicht eindeutig.');
    } else if (hatErinnerung) {
      belegtyp = 'Zahlungserinnerung';
    } else if (hatMahnung) {
      belegtyp = 'Mahnung';
    } else {
      probleme.push('Titel "' + titel + '" enthaelt weder "Zahlungserinnerung" noch "Mahnung".');
    }

    if (/^RG-\d+-\d+$/.test(teile[1])) {
      rechnung = teile[1];
    } else {
      probleme.push('Rechnungsnummer "' + teile[1] + '" passt nicht auf RG-<n>-<n>.');
    }

    const d = teile[2];
    if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) {
      probleme.push('Belegdatum "' + d + '" ist nicht als YYYY-MM-DD geschrieben.');
    } else {
      const j  = Number(d.slice(0, 4));
      const m  = Number(d.slice(5, 7));
      const tg = Number(d.slice(8, 10));
      const zurueck = new Date(Date.UTC(j, m - 1, tg)).toISOString().slice(0, 10);
      if (zurueck !== d) {
        probleme.push('Belegdatum "' + d + '" gibt es im Kalender nicht.');
      } else {
        datum = d;
      }
    }
  }
}

if (probleme.length) {
  return Object.assign({}, leer, {
    status: 'problem',
    betreff: betreff,
    hinweis: probleme.join(' ')
  });
}

const q = function (s) { return String(s).replace(/"/g, '\\"'); };

const fUms = '{ID} = "' + q(rechnung) + '"';
const fBlg = 'AND({Belegtyp} = "' + q(belegtyp) + '", ' +
             'DATETIME_FORMAT({Datum}, "YYYY-MM-DD") = "' + q(datum) + '", ' +
             '{Umsatz} = "' + q(rechnung) + '")';

return {
  status: 'pruefen',
  hinweis: '',
  belegtyp: belegtyp,
  rechnung: rechnung,
  datum: datum,
  betreff: betreff,
  dateiname: rechnung + '_' + belegtyp + '.pdf',
  url_umsatz: 'https://api.airtable.com/v0/' + BASE + '/' + T_UMS +
              '?maxRecords=2&filterByFormula=' + encodeURIComponent(fUms),
  url_dublette: 'https://api.airtable.com/v0/' + BASE + '/' + T_BLG +
                '?maxRecords=1&filterByFormula=' + encodeURIComponent(fBlg)
};

// ctx als fertiger JSON-Text — ein Mailbetreff kann Anfuehrungszeichen
// tragen und wuerde den JSON-Body sonst zerlegen.
return { ctx: JSON.stringify({
  'Betreff': String(input.betreff || ''),
  'Hinweis': String(input.hinweis || '')
}) };

// -- Modul 7 - Verdikt ----------------------------------------------------
// Drei Ausgaenge: anlegen, dublette (still verwerfen), problem (melden).
// Zusaetzlich wird der Ziel-Status fuer den Umsatz bestimmt (status_ziel):
//   Zahlungserinnerung -> "Ueberfaellig", Mahnung -> "Angemahnt".
// status_set = "1" nur, wenn wirklich geschrieben werden soll. Der Guard
// verhindert JEDES Downgrade: terminale/bezahlte Status bleiben unangetastet,
// eine Zahlungserinnerung stuft ein bestehendes "Angemahnt" nicht zurueck,
// ein bereits gesetzter Zielwert wird nicht redundant geschrieben.

const parse = function (v) {
  return (typeof v === 'string' ? (v ? JSON.parse(v) : null) : v);
};

const ums = parse(input.ums_body) || {};
const dup = parse(input.dup_body) || {};
const stU = String(input.ums_status || '');
const stD = String(input.dup_status || '');

const rechnung = String(input.rechnung || '');
const belegtyp = String(input.belegtyp || '');
const datum    = String(input.datum || '');

const leerStatus = { status_ziel: '', status_set: '0' };

const probleme = [];

if (stU !== '200') probleme.push('Umsatz-Abfrage fehlgeschlagen (HTTP ' + stU + ').');
if (stD !== '200') probleme.push('Dubletten-Abfrage fehlgeschlagen (HTTP ' + stD + ').');

const treffer = ums.records || [];
const dubl    = dup.records || [];

if (!probleme.length) {
  if (treffer.length === 0) {
    probleme.push('Zu ' + rechnung + ' gibt es keinen Umsatz in Airtable.');
  } else if (treffer.length > 1) {
    probleme.push('Zu ' + rechnung + ' gibt es mehr als einen Umsatz.');
  }
}

if (probleme.length) {
  return Object.assign({
    verdikt: 'problem',
    umsatz_id: '',
    text: '\u26a0\ufe0f <b>' + belegtyp + ' konnte nicht abgelegt werden</b>\n' +
          rechnung + ' \u00b7 ' + datum + '\n\n' + probleme.join(' ')
  }, leerStatus);
}

// Gleicher Umsatz, gleicher Belegtyp, gleiches Belegdatum: schon abgelegt.
if (dubl.length > 0) {
  return Object.assign({ verdikt: 'dublette', umsatz_id: '', text: '' }, leerStatus);
}

// -- Ziel-Status bestimmen (nur beim tatsaechlichen Anlegen) --------------
// Modul 5 laeuft mit returnFieldsByFieldId=true, der aktuelle Status steht
// deshalb unter der Feld-ID (Status = fldBavq4sjk2A1swZ) und als Klartext-Name.
const rec     = treffer[0] || {};
const felder  = rec.fields || {};
const aktuell = String(felder['fldBavq4sjk2A1swZ'] || '');

// Rangordnung: Storniert/Ausgebucht > Bezahlt > Teilgezahlt > Angemahnt >
// Ueberfaellig > Offen. Die Mahnkette fasst nur Offen/Ueberfaellig an,
// eine Mahnung zusaetzlich Angemahnt (Selbst-Ersatz). Alles darueber bleibt.
const NICHT_ANFASSEN = { 'Bezahlt': 1, 'Teilgezahlt': 1, 'Storniert': 1, 'Ausgebucht': 1 };

let ziel = '';
if (!NICHT_ANFASSEN[aktuell]) {
  if (belegtyp === 'Mahnung') {
    ziel = 'Angemahnt';
  } else if (belegtyp === 'Zahlungserinnerung') {
    ziel = (aktuell === 'Angemahnt') ? '' : '\u00dcberf\u00e4llig';
  }
}
if (ziel === aktuell) ziel = '';   // kein redundanter Schreibvorgang

return {
  verdikt: 'anlegen',
  umsatz_id: String(rec.id || ''),
  text: '\ud83d\udcc4 <b>' + belegtyp + ' abgelegt</b>\n' +
        rechnung + ' \u00b7 ' + datum,
  status_ziel: ziel,
  status_set: ziel ? '1' : '0'
};

// -- Modul 12 - Meldung ---------------------------------------------------
// Der Beleg steht zu diesem Zeitpunkt bereits in Airtable. Scheitert nur
// der Upload, wird der Datensatz NICHT zurueckgerollt - ein halber Beleg
// ist auffindbar, ein geloeschter nicht. Die Meldung nennt dann die
// Record-ID, damit das PDF von Hand nachgezogen werden kann.

const st = String(input.status || '');
const dateiname = String(input.dateiname || '');

const belegtyp = String(input.belegtyp || '');
const klingel = {
  key: (belegtyp === 'Mahnung') ? 'invoice.dunning_filed' : 'invoice.reminder_filed',
  ctx: JSON.stringify({ 'Belegtyp': belegtyp })
};

if (st === '200') {
  return Object.assign({ text: String(input.erfolg || '') + '\n' + dateiname }, klingel);
}

const parse = function (v) {
  return (typeof v === 'string' ? (v ? JSON.parse(v) : null) : v);
};
const b = parse(input.body) || {};

return Object.assign(klingel, {
  text: '\u26a0\ufe0f <b>Beleg angelegt, PDF fehlt</b>\n' +
        String(input.record || '') + '\n\n' +
        'Upload fehlgeschlagen (HTTP ' + st + '): ' +
        JSON.stringify(b).slice(0, 300) + '\n\n' +
        'Das PDF haengt an der Mail und muss von Hand an den Datensatz.'
});


// ── Klingel-Nutzlast ───────────────────────────────────────────────────
// Der Belegtyp entscheidet den Schluessel: Teil B Typ 9 gegen Typ 10.
// Achtung: der Zweig "Beleg angelegt, PDF fehlt" hat im Katalog KEINEN
// eigenen Meldetyp — task.beleg_no_pdf ist reine Digest-Zeile. Bis der
// Digest steht, faellt dieser Hinweis unter den Tisch.
// (nicht Teil des Rueckgabewerts oben — siehe zweiten return unten)
